static inline std::optional<std::string> lookup_continent(int lat, int lon)
{
  if (lat < LAT_MIN || lat > LAT_MAX || lon < LON_MIN || lon > LON_MAX) {
    return std::nullopt;
  }
  uint8_t idx = MAP[lat - LAT_MIN][lon - LON_MIN];
  if (idx == SRTM_NO_DATA) {
    return std::nullopt;
  }
  return std::string(CONTINENTS[idx]);
}

